<?php

declare(strict_types=1);

namespace App\Models;

use App\Support\Ids\HasPrefixedId;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Support\Carbon;

/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $name
 * @property string $kind
 * @property string $status
 * @property string|null $audience
 * @property array|null $rules
 * @property Carbon|null $starts_at
 * @property Carbon|null $ends_at
 * @property string|null $created_by
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class Campaign extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'cmp';

    protected $fillable = [
        'name', 'kind', 'status', 'audience', 'rules', 'starts_at', 'ends_at', 'created_by',
    ];

    protected function casts(): array
    {
        return [
            'rules' => 'array',
            'starts_at' => 'datetime',
            'ends_at' => 'datetime',
        ];
    }

    /** @return HasMany<PromoCode, $this> */
    public function promoCodes(): HasMany
    {
        return $this->hasMany(PromoCode::class);
    }
}
